const b = $('Webhook Trimite').item.json.body || {};
const msg = b.message || '';
const t = b.tip_postare || '';
const teamId = b.teamId || '';
const channelId = b.channelId || '';
const channelName = b.channelName || 'General';
const title = t.replace(/^[A-F]\. /, '');
const extra = Array.isArray(b.mentions) ? b.mentions : [];

const graphMentions = [ { id: 0, mentionText: channelName, mentioned: { conversation: { id: channelId, displayName: channelName, conversationIdentityType: 'channel' } } } ];
let nextId = 1;

const htmlMsg = msg.replace(/@\[([^\]]+)\]/g, function(match, name){
  const info = extra.find(function(m){ return m.displayName === name; });
  if (!info) return match;
  if (info.type === 'channel' && info.id) {
    const id = nextId++;
    graphMentions.push({ id: id, mentionText: name, mentioned: { conversation: { id: info.id, displayName: name, conversationIdentityType: 'channel' } } });
    return '<at id="' + id + '">' + name + '</at>';
  }
  if ((info.type === 'user' || info.type === 'external') && info.id) {
    const id = nextId++;
    graphMentions.push({ id: id, mentionText: name, mentioned: { user: { id: info.id, displayName: name, userIdentityType: 'aadUser' } } });
    return '<at id="' + id + '">' + name + '</at>';
  }
  return '<strong>' + name + (info.email ? ' (' + info.email + ')' : '') + '</strong>';
}).split('\n').join('<br>');

const bodyContent = '<at id="0">' + channelName + '</at><br><br>' + htmlMsg;
const graphBody = { subject: title, body: { contentType: 'html', content: bodyContent }, mentions: graphMentions };
const url = 'https://graph.microsoft.com/v1.0/teams/' + teamId + '/channels/' + channelId + '/messages';
return [{ json: { url: url, graphBody: graphBody } }];

